const NON_CLAIMS: &str =
    "correctness,semantic_equivalence,exhaustive_rust_coverage,cross_machine_determinism,cross_toolchain_determinism";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EvidenceIndexInput {
    pub capture_time: String,
    pub payload_commit: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EvidenceIndexCheckReport {
    pub valid: bool,
    pub issue_codes: Vec<&'static str>,
}

#[must_use]
pub fn check_page_text(text: &str) -> EvidenceIndexCheckReport {
    check_page_text_with_expected(text, None, None)
}

#[must_use]
pub fn check_page_text_with_expected(
    text: &str,
    expected_payload_commit: Option<String>,
    expected_capture_time: Option<String>,
) -> EvidenceIndexCheckReport {
    let mut issue_codes = Vec::new();
    let Some(mut input) = extract_input(text) else {
        return EvidenceIndexCheckReport {
            valid: false,
            issue_codes: vec!["missing_capture_or_payload"],
        };
    };

    if let Some(payload_commit) = expected_payload_commit {
        if input.payload_commit != payload_commit {
            issue_codes.push("payload_commit_mismatch");
        }
        input.payload_commit = payload_commit;
    }
    if let Some(capture_time) = expected_capture_time {
        if input.capture_time != capture_time {
            issue_codes.push("capture_time_mismatch");
        }
        input.capture_time = capture_time;
    }

    let expected = render_valence_evidence_index(&input);
    if text != expected {
        collect_mismatches(text, &expected, &mut issue_codes);
        if issue_codes.is_empty() {
            issue_codes.push("markdown_mismatch");
        }
    }

    issue_codes.sort_unstable();
    issue_codes.dedup();
    EvidenceIndexCheckReport {
        valid: issue_codes.is_empty(),
        issue_codes,
    }
}

