fn extract_input(text: &str) -> Option<EvidenceIndexInput> {
    let capture_time = text.lines().find_map(|line| line.strip_prefix("Capture time: "))?.to_owned();
    let payload_line = text.lines().find_map(|line| line.strip_prefix("Verified code commit: `"))?;
    let payload_commit = payload_line.split('`').next()?.to_owned();
    Some(EvidenceIndexInput {
        capture_time,
        payload_commit,
    })
}

fn collect_mismatches(text: &str, expected: &str, issue_codes: &mut Vec<&'static str>) {
    if !text.contains("Verified code commit: `") {
        issue_codes.push("payload_commit_missing");
    } else if extract_input(text).map(|input| input.payload_commit).as_deref()
        != extract_input(expected).map(|input| input.payload_commit).as_deref()
    {
        issue_codes.push("payload_commit_mismatch");
    }

    for marker in required_markers() {
        if !text.contains(marker.text) {
            issue_codes.push(marker.issue_code);
        }
    }

    for line in expected.lines() {
        if line.starts_with("valence_object_evidence.") && !text.contains(line) {
            issue_codes.push("aggregate_pass_signal_missing");
        }
    }
}

struct RequiredMarker {
    text: &'static str,
    issue_code: &'static str,
}

fn required_markers() -> &'static [RequiredMarker] {
    &[
        RequiredMarker {
            text: "- Named evidence-index freshness rail: `nix build .#checks.x86_64-linux.valence-evidence-index --no-link -L`.",
            issue_code: "evidence_index_rail_missing",
        },
        RequiredMarker {
            text: "valence_object_evidence.evidence_index_gate: PASS\n",
            issue_code: "evidence_index_pass_missing",
        },
        RequiredMarker {
            text: "valence_object_evidence.supplement_compatibility_gate: PASS\n",
            issue_code: "supplement_compatibility_pass_missing",
        },
        RequiredMarker {
            text: "not a correctness proof, semantic-equivalence proof, exhaustive Rust coverage proof",
            issue_code: "non_claims_weakened",
        },
        RequiredMarker {
            text: "cross-machine determinism proof, cross-toolchain determinism proof, or general HIR/THIR/MIR extraction claim",
            issue_code: "determinism_non_claims_weakened",
        },
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_input() -> EvidenceIndexInput {
        EvidenceIndexInput {
            capture_time: "2026-05-23T12:00:00Z".to_owned(),
            payload_commit: "0123456789abcdef0123456789abcdef01234567".to_owned(),
        }
    }

    #[test]
    fn evidence_index_render_roundtrips_through_check() {
        let rendered = render_valence_evidence_index(&sample_input());
        let report = check_page_text(&rendered);
        assert_eq!(report.issue_codes, Vec::<&'static str>::new());
        assert!(report.valid);
    }

    #[test]
    fn evidence_index_check_fails_closed_for_stale_payload_commit() {
        let rendered = render_valence_evidence_index(&sample_input());
        let stale =
            rendered.replace("0123456789abcdef0123456789abcdef01234567", "fedcba9876543210fedcba9876543210fedcba98");
        let report =
            check_page_text_with_expected(&stale, Some("0123456789abcdef0123456789abcdef01234567".to_owned()), None);
        assert!(!report.valid);
        assert!(report.issue_codes.contains(&"payload_commit_mismatch"));
    }

    #[test]
    fn evidence_index_check_fails_closed_for_missing_rail() {
        let rendered = render_valence_evidence_index(&sample_input());
        let missing = rendered.replace(
            "- Named evidence-index freshness rail: `nix build .#checks.x86_64-linux.valence-evidence-index --no-link -L`.\n",
            "",
        );
        let report = check_page_text(&missing);
        assert!(!report.valid);
        assert!(report.issue_codes.contains(&"evidence_index_rail_missing"));
    }

    #[test]
    fn evidence_index_check_fails_closed_for_missing_pass_signal() {
        let rendered = render_valence_evidence_index(&sample_input());
        let missing = rendered.replace("valence_object_evidence.evidence_index_gate: PASS\n", "");
        let report = check_page_text(&missing);
        assert!(!report.valid);
        assert!(report.issue_codes.contains(&"evidence_index_pass_missing"));
    }

    #[test]
    fn evidence_index_check_fails_closed_for_weakened_non_claims() {
        let rendered = render_valence_evidence_index(&sample_input());
        let weakened = rendered.replace(
            "It is not a correctness proof, semantic-equivalence proof, exhaustive Rust coverage proof, pure-cache eligibility proof, public unattended production-readiness claim, cross-machine determinism proof, cross-toolchain determinism proof, or general HIR/THIR/MIR extraction claim.",
            "It is bounded evidence.",
        );
        let report = check_page_text(&weakened);
        assert!(!report.valid);
        assert!(report.issue_codes.contains(&"non_claims_weakened"));
        assert!(report.issue_codes.contains(&"determinism_non_claims_weakened"));
    }
}
